from .repository import move, balance


def transfer(connection, publisher, source, target, amount):
    # Validation: no writes, no publication on invalid input.
    if source == target:
        raise ValueError("source and target must differ")
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError("amount must be a positive integer")
    if amount <= 0:
        raise ValueError("amount must be a positive integer")
    if balance(connection, source) is None:
        raise ValueError("source account does not exist")
    if balance(connection, target) is None:
        raise ValueError("target account does not exist")
    if balance(connection, source) < amount:
        raise ValueError("insufficient balance")

    # Apply and commit; any database failure rolls back and never publishes.
    try:
        move(connection, source, target, amount)
        connection.commit()
    except Exception:
        try:
            connection.rollback()
        except Exception:
            pass
        raise

    # Publish only after a committed transfer; failure propagates without undo.
    publisher.publish({"source": source, "target": target, "amount": amount})
